////", 30, 40)\noled.text("(`3`)y", 30, 55)\noled.show()  # Show the text\n'})}),"\n",(0,o.jsx)(n.h4,{id:"2-loading-dynamic-effect",children:"2. Loading dynamic effect"}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{width:500,src:"https://files.seeedstudio.com/wiki/wiki-ranger/Contributions/C3-MicroPy/C3-MicroPython8.png"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-cpp",children:"import time\nfrom machine import Pin, SoftI2C\nimport ssd1306\nimport math\n\n# ESP8266 Pin assignment\ni2c = SoftI2C(scl=Pin(7), sda=Pin(6))  # Adjust the Pin numbers based on your connections\noled_width = 128\noled_height = 64\noled = ssd1306.SSD1306_I2C(oled_width, oled_height, i2c)\n\ncenter_x = oled_width // 2\ncenter_y = oled_height // 2\nsquare_size = 6  # Size of each square\nnum_squares = 12  # Number of squares\nangle_increment = 2 * math.pi / num_squares\n\nwhile True:\n    oled.fill(0)  # Clear the screen\n\n    for i in range(num_squares):\n        angle = i * angle_increment\n        x = int(center_x + (center_x - square_size-30) * math.cos(angle))\n        y = int(center_y + (center_x - square_size-30) * math.sin(angle))\n\n        # Draw all squares\n        for j in range(num_squares):\n            angle_j = j * angle_increment\n            x_j = int(center_x + (center_x - square_size-30) * math.cos(angle_j))\n            y_j = int(center_y + (center_x - square_size-30) * math.sin(angle_j))\n\n            oled.fill_rect(x_j, y_j, square_size, square_size, 1)  # Draw the square\n\n        oled.fill_rect(x, y, square_size, square_size, 0)  # Erase the current square\n        oled.show()\n        time.sleep_ms(100)  # Pause before next iteration\n\n"})}),"\n",(0,o.jsx)(n.h3,{id:"demo-2-light-a-buzzer",children:"Demo 2: Light a Buzzer"}),"\n",(0,o.jsx)(n.h4,{id:"1-sound",children:"1. Sound"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-cpp",children:"import time\nfrom time import sleep\nimport machine\nfrom machine import Pin, SoftI2C\n\n\n# Buzzer settings\n\nbuzzer_pin = machine.Pin(5, machine.Pin.OUT)\nbuzzer = machine.PWM(buzzer_pin)\nbuzzer.freq(1047)\n\n# Buzzer working\n\nwhile True:\n\n    buzzer.duty(10)\n    time.sleep(1)\n    buzzer.duty(0)\n    time.sleep(1)\n"})}),"\n",(0,o.jsx)(n.h4,{id:"2-play-the-song-hes-a-pirate",children:'2. Play the Song "He\'s a pirate"'}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-python",children:"import machine\nimport time\n\n# Buzzer settings\nbuzzer_pin = machine.Pin(5, machine.Pin.OUT)\nbuzzer = machine.PWM(buzzer_pin)\nbuzzer.freq(1047)\n\n# Defining frequency of each music note\nNOTE_C4 = 262\nNOTE_D4 = 294\nNOTE_E4 = 330\nNOTE_F4 = 349\nNOTE_G4 = 392\nNOTE_A4 = 440\nNOTE_B4 = 494\nNOTE_C5 = 523\nNOTE_D5 = 587\nNOTE_E5 = 659\nNOTE_F5 = 698\nNOTE_G5 = 784\nNOTE_A5 = 880\nNOTE_B5 = 988\n\n# Music notes of the song, 0 is a rest/pulse\nnotes = [\n    NOTE_E4, NOTE_G4, NOTE_A4, NOTE_A4, 0,\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_C5, NOTE_D5, NOTE_B4, NOTE_B4, 0,\n    NOTE_A4, NOTE_G4, NOTE_A4, 0,\n\n    NOTE_E4, NOTE_G4, NOTE_A4, NOTE_A4, 0,\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_C5, NOTE_D5, NOTE_B4, NOTE_B4, 0,\n    NOTE_A4, NOTE_G4, NOTE_A4, 0,\n\n    NOTE_E4, NOTE_G4, NOTE_A4, NOTE_A4, 0,\n    NOTE_A4, NOTE_C5, NOTE_D5, NOTE_D5, 0,\n    NOTE_D5, NOTE_E5, NOTE_F5, NOTE_F5, 0,\n    NOTE_E5, NOTE_D5, NOTE_E5, NOTE_A4, 0,\n\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_D5, NOTE_E5, NOTE_A4, 0,\n    NOTE_A4, NOTE_C5, NOTE_B4, NOTE_B4, 0,\n    NOTE_C5, NOTE_A4, NOTE_B4, 0,\n\n    NOTE_A4, NOTE_A4,\n    #Repeat of first part\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_C5, NOTE_D5, NOTE_B4, NOTE_B4, 0,\n    NOTE_A4, NOTE_G4, NOTE_A4, 0,\n\n    NOTE_E4, NOTE_G4, NOTE_A4, NOTE_A4, 0,\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_C5, NOTE_D5, NOTE_B4, NOTE_B4, 0,\n    NOTE_A4, NOTE_G4, NOTE_A4, 0,\n\n    NOTE_E4, NOTE_G4, NOTE_A4, NOTE_A4, 0,\n    NOTE_A4, NOTE_C5, NOTE_D5, NOTE_D5, 0,\n    NOTE_D5, NOTE_E5, NOTE_F5, NOTE_F5, 0,\n    NOTE_E5, NOTE_D5, NOTE_E5, NOTE_A4, 0,\n\n    NOTE_A4, NOTE_B4, NOTE_C5, NOTE_C5, 0,\n    NOTE_D5, NOTE_E5, NOTE_A4, 0,\n    NOTE_A4, NOTE_C5, NOTE_B4, NOTE_B4, 0,\n    NOTE_C5, NOTE_A4, NOTE_B4, 0,\n    #End of Repeat\n\n    NOTE_E5, 0, 0, NOTE_F5, 0, 0,\n    NOTE_E5, NOTE_E5, 0, NOTE_G5, 0, NOTE_E5, NOTE_D5, 0, 0,\n    NOTE_D5, 0, 0, NOTE_C5, 0, 0,\n    NOTE_B4, NOTE_C5, 0, NOTE_B4, 0, NOTE_A4,\n\n    NOTE_E5, 0, 0, NOTE_F5, 0, 0,\n    NOTE_E5, NOTE_E5, 0, NOTE_G5, 0, NOTE_E5, NOTE_D5, 0, 0,\n    NOTE_D5, 0, 0, NOTE_C5, 0, 0,\n    NOTE_B4, NOTE_C5, 0, NOTE_B4, 0, NOTE_A4\n]\n\n# Dura\xe7\xf5es (em ms) de cada nota musical da m\xfasica\n# Nota Sem\xednima \xe9 250 ms quando songSpeed = 1.0\ndurations = [\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 125,\n\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 125,\n\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 125, 250, 125,\n\n    125, 125, 250, 125, 125,\n    250, 125, 250, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 375,\n\n    250, 125,\n    #Rpeat of First Part\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 125,\n\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 125,\n\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 125, 250, 125,\n\n    125, 125, 250, 125, 125,\n    250, 125, 250, 125,\n    125, 125, 250, 125, 125,\n    125, 125, 375, 375,\n    #End of Repeat\n\n    250, 125, 375, 250, 125, 375,\n    125, 125, 125, 125, 125, 125, 125, 125, 375,\n    250, 125, 375, 250, 125, 375,\n    125, 125, 125, 125, 125, 500,\n\n    250, 125, 375, 250, 125, 375,\n    125, 125, 125, 125, 125, 125, 125, 125, 375,\n    250, 125, 375, 250, 125, 375,\n    125, 125, 125, 125, 125, 500\n]\n\ndef play_song():\n    total_notes = len(notes)\n    for i in range(total_notes):\n        current_note = notes[i]\n        wait = durations[i]\n        if current_note != 0:\n            buzzer.duty(512)  # Set duty cycle for sound\n            buzzer.freq(current_note)  # Set frequency of the note\n        else:\n            buzzer.duty(0)  # Turn off the sound\n        time.sleep_ms(wait)\n        buzzer.duty(0)  # Turn off the sound\nwhile True:\n    # Play the song\n    play_song()\n"})}),"\n",(0,o.jsx)(n.h3,{id:"demo-3-connect-to-wi-fi",children:"Demo 3: Connect to Wi-fi"}),"\n",(0,o.jsx)(n.h4,{id:"1-connect-to-wi-fi",children:"1. Connect to Wi-fi"}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{width:500,src:"https://files.seeedstudio.com/wiki/wiki-ranger/Contributions/C3-MicroPy/C3-MicroPython8a.png"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-python",children:'import network\nimport urequests\nimport utime as time\n\n# Configura\xe7\xf5es de rede\nwifi_ssid = "Your Own SSID"\nwifi_password = "Your Own Password"\n\ndef scan_and_connect():\n    station = network.WLAN(network.STA_IF)\n    station.active(True)\n\n    print("Scanning for WiFi networks, please wait...")\n    for ssid, bssid, channel, RSSI, authmode, hidden in station.scan():\n        print("* {:s}".format(ssid))\n        print("   - Channel: {}".format(channel))\n        print("   - RSSI: {}".format(RSSI))\n        print("   - BSSID: {:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}".format(*bssid))\n        print()\n\n    while not station.isconnected():\n        print("Connecting...")\n        station.connect(wifi_ssid, wifi_password)\n        time.sleep(10)\n\n    print("Connected!")\n    print("My IP Address:", station.ifconfig()[0])\n\n\n# Executar as fun\xe7\xf5es\nscan_and_connect()\n'})}),"\n",(0,o.jsx)(n.h4,{id:"2-request-new-york-time-online",children:"2. Request New York Time online"}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{width:500,src:"https://files.seeedstudio.com/wiki/wiki-ranger/Contributions/C3-MicroPy/C3-MicroPython9.png"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-cpp",children:'from machine import Pin, SoftI2C\nimport ssd1306\nfrom time import sleep\nimport time\nimport network\nimport urequests\nimport ujson\n\n# Atribui\xe7\xe3o de pinos do ESP32\n# i2c = SoftI2C(scl=Pin(22), sda=Pin(21))\n\n# Atribui\xe7\xe3o de pinos do ESP8266\ni2c = SoftI2C(scl=Pin(7), sda=Pin(6))  # Adjust the Pin numbers based on your connections\n\noled_width = 128\noled_height = 64\noled = ssd1306.SSD1306_I2C(oled_width, oled_height, i2c)\n\nstation = network.WLAN(network.STA_IF)\nstation.active(True)\n\n# Configura\xe7\xf5es de rede\nwifi_ssid = "Your wifi ssid"\nwifi_password = "Your wifi password"\nurl = "http://worldtimeapi.org/api/timezone/America/New_York"\n\nprint("Scanning for WiFi networks, please wait...")\nauthmodes = [\'Open\', \'WEP\', \'WPA-PSK\' \'WPA2-PSK4\', \'WPA/WPA2-PSK\']\nfor (ssid, bssid, channel, RSSI, authmode, hidden) in station.scan():\n    print("* {:s}".format(ssid))\n    print("   - Channel: {}".format(channel))\n    print("   - RSSI: {}".format(RSSI))\n    print("   - BSSID: {:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}".format(*bssid))\n    print()\n\n# Tentar continuamente conectar ao ponto de acesso WiFi\nwhile not station.isconnected():\n    # Tentar conectar ao ponto de acesso WiFi\n    print("Connecting...")\n    station.connect(wifi_ssid, wifi_password)\n    time.sleep(10)\n\n# Exibir detalhes da conex\xe3o\nprint("Connected!")\nprint("My IP Address:", station.ifconfig()[0])\n\n\nwhile True:\n    # Realizar requisi\xe7\xe3o HTTP GET em uma web sem SSL\n    response = urequests.get(url)\n    # Verificar se a requisi\xe7\xe3o foi bem-sucedida\n    if response.status_code == 200:\n        # Analisar a resposta JSON\n        data = ujson.loads(response.text)\n        # Extrair o campo "datetime" para Nova York\n        ny_datetime = data["datetime"]\n        # Dividir os componentes de data e hora\n        date_part, time_part = ny_datetime.split("T")\n        # Obter apenas as duas primeiras casas decimais do hor\xe1rio\n        time_part = time_part[:8]\n        # Obter o fuso hor\xe1rio\n        timezone = data["timezone"]\n\n        # Limpar o display OLED\n        oled.fill(0)\n\n        # Exibir a data e hora de Nova York em linhas separadas\n        oled.text("New York Date:", 0, 0)\n        oled.text(date_part, 0, 10)\n        oled.text("New York Time:", 0, 20)\n        oled.text(time_part, 0, 30)\n        oled.text("Timezone:", 0, 40)\n        oled.text(timezone, 0, 50)\n        # Atualizar o display\n        oled.show()\n    else:\n        oled.text("Failed to get the time for New York!")\n        # Atualizar o display\n        oled.show()\n'})}),"\n",(0,o.jsx)(n.h3,{id:"final-wi-fi-signal-strength-tracker",children:"Final: Wi-fi Signal Strength Tracker"}),"\n",(0,o.jsx)(n.p,{children:"This  is the  main task in this project. Through this code, you can trake your wifi signal at home with such an easy device."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{width:800,src:"https://files.seeedstudio.com/wiki/wiki-ranger/Contributions/C3-MicroPy/C3-MicroPython10.jpg"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-cpp",children:'import network\nimport time\nfrom time import sleep\nimport machine\nfrom machine import Pin, SoftI2C\nimport ssd1306\nimport math\n\n# Atribui\xe7\xe3o de pinos do ESP32C3\ni2c = SoftI2C(scl=Pin(7), sda=Pin(6))  # Adjust the Pin numbers based on your connections\noled_width = 128\noled_height = 64\noled = ssd1306.SSD1306_I2C(oled_width, oled_height, i2c)\n\n# Configura\xe7\xf5es de rede\nwifi_ssid = "Your Own SSID"\nwifi_password = "Your Own Password"\nmachine.freq(160000000)  # Set CPU frequency to 160 MHz (ESP8266 specific)\noled.text("Starting up...", 0, 0)\noled.show()\n\nstation = network.WLAN(network.STA_IF)\nstation.active(True)\nstation.connect(wifi_ssid, wifi_password)\ntime.sleep(1)\n\nwhile not station.isconnected():\n    time.sleep(1)\n\noled.fill(0)\noled.text("Connecting to", 0, 0)\noled.text(wifi_ssid, 0, 20)\noled.show()\ntime.sleep(2)\n\noled.fill(0)\nip_address = station.ifconfig()[0]  # Get the IP address\noled.text("Connected! ", 0, 0)\noled.text("IP Address:", 0, 20)\noled.text(ip_address, 0, 40)\noled.show()\ntime.sleep(2)\n\n# Configura\xe7\xf5es do buzzer\nbuzzer_pin = machine.Pin(5, machine.Pin.OUT)\nbuzzer = machine.PWM(buzzer_pin)\nbuzzer.freq(1047)\nbuzzer.duty(0)\n\ncenter_x = oled_width // 2\ncenter_y = oled_height // 2\nsquare_size = 6  # Size of each square\nnum_squares = 12  # Number of squares\nangle_increment = 2 * math.pi / num_squares\n\nx_pos = [12, 38, 64, 90]\nstatuses = ["poor", "normal", "good", "excellent"]\n\ndef calculate_block_count(rssi):\n    # Determinar o n\xfamero de blocos com base nos valores de RSSI\n    if -80 <= rssi < -60:\n        return 1\n    elif -60 <= rssi < -40:\n        return 2\n    elif -40 <= rssi < -20:\n        return 3\n    elif -20 <= rssi <= 10:\n        return 4\n\ndef draw_blocks(count):\n    for i in range(count):\n        y_pos = 50 - calculate_block_height(i)\n        oled.fill_rect(x_pos[i], y_pos, 24, calculate_block_height(i), 1)\n    for i in range(count, 4):  # Clear unused area\n        y_pos = 50 - calculate_block_height(i)\n        oled.fill_rect(x_pos[i], y_pos, 24, calculate_block_height(i), 0)\n\ndef calculate_block_height(index):\n    return 10 * (index + 1)\n\nloop_count = 0  # Inicializar contagem de loops\n\nwhile loop_count < 2:  # Executar o loop 24 vezes\n    oled.fill(0)  # Limpar a tela\n\n    for i in range(num_squares):\n        angle = i * angle_increment\n        x = int(center_x + (center_x - square_size-30) * math.cos(angle))\n        y = int(center_y + (center_x - square_size-30) * math.sin(angle))\n\n        # Desenhar todos os quadrados\n        for j in range(num_squares):\n            angle_j = j * angle_increment\n            x_j = int(center_x + (center_x - square_size-30) * math.cos(angle_j))\n            y_j = int(center_y + (center_x - square_size-30) * math.sin(angle_j))\n\n            oled.fill_rect(x_j, y_j, square_size, square_size, 1)  # Draw the square\n\n        oled.fill_rect(x, y, square_size, square_size, 0)  # Erase the current square\n        oled.show()\n        time.sleep_ms(100)  # Pause before next iteration\n\n    loop_count += 1  # Aumentar contagem de loops\n\noled.fill(0)  # Limpar a tela ap\xf3s finalizar os loops\noled.show()\n\nwhile True:\n    oled.fill(0)\n    station = network.WLAN(network.STA_IF)\n    time.sleep(0.1)\n    rssi = station.status(\'rssi\')\n    rssi_duty = 160 + 2 * int(rssi)\n    rssi_duty_2 = int(rssi_duty / 2)\n    rssi_abs = abs(int(rssi)) / 100\n\n    block_count = calculate_block_count(rssi)\n    status = statuses[block_count - 1]  # Get the status text based on block count\n\n    draw_blocks(block_count)\n\n    oled.text(status, 11, 56)\n\n    oled.text("RSSI:", 0, 0)\n    oled.text(str(rssi), 40, 0)\n    # Update the display\n    oled.show()\n\n    buzzer.duty(rssi_duty)\n    time.sleep(rssi_abs)\n    buzzer.duty(0)\n    time.sleep(rssi_abs)\n    buzzer.duty(rssi_duty_2)\n    time.sleep(rssi_abs)\n    buzzer.duty(0)\n    time.sleep(rssi_abs)\n\n'})}),"\n",(0,o.jsx)(n.h2,{id:"whats-more",children:"What's more"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"You can also flash firmware into XIAO ESP32C3 using esptool intergated on Thonny which is supportive for MAC OS."}),"\n"]}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{width:800,src:"https://files.seeedstudio.com/wiki/wiki-ranger/Contributions/C3-MicroPy/C3-MicroPython11.png"})}),"\n",(0,o.jsx)(n.h2,{id:"-contributor-project",children:"\u2728 Contributor Project"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{childr